'ddl_md5',CASE WHEN p.oid=to_regprocedure('combat_v2_staff_nb_internal.commit_roster(jsonb)') THEN '6b1916b065f043a2203baeb3e675f346' WHEN p.oid=to_regprocedure('combat_panel_private.publish_master_declaration(uuid,text)') THEN '6455607f34c43dfb0b6d222cd1962f97' WHEN p.oid=to_regprocedure('clan_innata_private.catalogo_eligibility_release_v1()') THEN 'b996bd0f1aba1218bd8af5477390f82c' ELSE md5(pg_get_functiondef(p.oid)) END,'owner',pg_get_userbyid(p.proowner),'secdef',p.prosecdef,
'config',p.proconfig,'acl',p.proacl::text,'volatility',p.provolatile::text) ORDER BY p.oid::regprocedure::text) AS metadata FROM pg_proc p WHERE p.oid IN ('clan_innata_private.catalogo_eligibility_release_v1()'::regprocedure,'clan_innata_private.eligibility_release_assert()'::regprocedure))
SELECT d0.descriptor descriptor_before,d1.descriptor descriptor_after,
 public.combat_v2_sha256(p0.metadata) peer6_before,public.combat_v2_sha256(p1.metadata) peer6_after,(SELECT jsonb_agg(b.v->>'signature') FROM jsonb_array_elements(p0.metadata) WITH ORDINALITY b(v,i) JOIN jsonb_array_elements(p1.metadata) WITH ORDINALITY a(v,i) USING(i) WHERE b.v IS DISTINCT FROM a.v) peer6_changes,
 public.combat_v2_sha256(c0.metadata) compat2_before, public.combat_v2_sha256(c1.metadata) compat2_after,(SELECT jsonb_agg(b.v->>'signature') FROM jsonb_array_elements(c0.metadata) WITH ORDINALITY b(v,i) JOIN jsonb_array_elements(c1.metadata) WITH ORDINALITY a(v,i) USING(i) WHERE b.v IS DISTINCT FROM a.v) compat2_changes,
 c0.metadata compat2_array_before,c1.metadata compat2_array_after
FROM d0,d1,p0,p1,c0,c1;
COMMIT;
